'use strict';
const beforeBusinessRender=render;let businessUser=null,businessData=null,businessLoading=false,businessMessage='',projectChoice='',businessLoadFailed=false;
async function businessApi(url,body,key){const r=await fetch('/api/ops/'+url,body?{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key||crypto.randomUUID()},body:JSON.stringify(body)}:{});const v=await r.json();if(!r.ok)throw Error(v.error||'业务请求失败');return v;}
async function refreshBusiness(){businessLoading=true;try{const session=await businessApi('session');businessUser=session.user;if(businessUser)businessData=await businessApi('snapshot');else businessData=null;if(businessLoadFailed)businessMessage='服务连接已恢复';businessLoadFailed=false;}catch(e){businessMessage=e.message;businessLoadFailed=true;businessData=null;}finally{businessLoading=false;if(page==='采购经营闭环')render();}}
const roleNames={applicant:'业务申请',approver:'预算审批',buyer:'采购执行',warehouse:'收货验收',finance:'财务登记'};
const actionNames={submit:'提交审批',approve:'批准',reject:'退回',order:'确认下单',receive:'验收通过',pay:'登记付款',cancel:'取消采购'};
function actionsFor(r,type){const role=businessUser?.role;let actions=[];if(role==='applicant'&&r.created_by===businessUser.id&&['草稿','已退回'].includes(r.status))actions=['submit'];if(role==='approver'&&r.status==='待审批')actions=['approve','reject'];if(type==='purchases'){if(role==='buyer'&&r.status==='已批准')actions=['order','cancel'];if(role==='buyer'&&r.status==='已下单')actions=['cancel'];if(role==='warehouse'&&r.status==='已下单')actions=['receive'];if(role==='finance'&&r.status==='已验收')actions=['pay'];}return actions.map(a=>`<button data-business-action="${a}" data-kind="${type}" data-id="${esc(r.id)}" data-version="${r.version}">${actionNames[a]}</button>`).join(' ');}
render=function(){if(page!=='采购经营闭环'){beforeBusinessRender();document.getElementById('nav').innerHTML+='<button data-page="采购经营闭环">采购经营闭环</button>';return;}document.getElementById('nav').innerHTML=['总览','采购经营闭环','业务数据','真实 AI 接入','操作日志'].map(n=>`<button data-page="${n}" class="${page===n?'active':''}">${n}</button>`).join('');app.innerHTML=`<div class="eyebrow">集团管理 AI / 服务端业务闭环</div><h1>立项、采购与经营台账</h1><div class="notice">SQLite 持久化 · 五类角色 · 金额按分计算 · 预算占用与付款联动。登记付款仅记录虚构账务，不连接银行。旧版浏览器模拟事项保留在原页面。</div><div id="business-content"></div>`;const c=document.getElementById('business-content');
if(!businessUser){c.innerHTML=`<div class="card"><h2>角色登录</h2><p class="muted">本机测试密码 demo123!。Render 部署后使用配置的演示密码。不同操作必须切换到对应账号，权限在服务端校验。</p><form id="business-login"><label><span>演示账号</span><select name="username">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}">${v} · ${k}</option>`).join('')}</select></label><label><span>密码</span><input name="password" type="password" required autocomplete="current-password"></label><button>登录</button></form><p role="status">${esc(businessMessage)}</p></div>`;return;}if(!businessData){c.innerHTML=`<div class="card"><p>${esc(businessMessage||'正在读取服务器数据…')}</p><button data-business="refresh">重新读取</button></div>`;return;}
const d=businessData,live=d.projects.filter(p=>p.id.startsWith('LIVE-')),choices=d.projects.filter(p=>p.status==='已批准');if(!projectChoice||!d.projects.some(p=>p.id===projectChoice))projectChoice=live[0]?.id||d.projects[0]?.id;const selectedProject=d.projects.find(p=>p.id===projectChoice);
c.innerHTML=`<div class="row between"><p>当前账号：<b>${esc(businessUser.name)}</b> · ${roleNames[businessUser.role]} · 基准记录 ${d.baselineCount.toLocaleString()}</p><div class="row"><button data-business="refresh" class="secondary">刷新服务器数据</button><button data-business="logout" class="secondary">退出并切换角色</button></div></div><p role="status">${esc(businessMessage)}</p><div class="stats"><div class="stat"><span>新增立项</span><strong>${live.length}</strong></div><div class="stat"><span>采购申请</span><strong>${d.purchases.length}</strong></div><div class="stat"><span>已验收回执</span><strong>${d.receipts.length}</strong></div><div class="stat"><span>已登记采购支出</span><strong style="font-size:1.4rem">${money(d.entries.reduce((n,e)=>n+e.amount,0))}</strong></div></div><div class="grid"><section><div class="card"><h2>项目立项与预算</h2>${businessUser.role==='applicant'?`<form id="business-project"><label><span>项目名称</span><input name="title" required maxlength="200" placeholder="面试样板音乐会"></label><label><span>预算（元）</span><input name="budget" type="number" min="0.01" step="0.01" value="50000" required></label><button>创建立项草稿</button></form>`:''}${live.length?live.map(p=>`<div class="item"><b>${esc(p.title)}</b> ${badge(p.status)}<div class="muted">${esc(p.id)} · v${p.version}<br>预算 ${money(p.budget)} · 已付 ${money(p.paid)} · 占用 ${money(p.committed)} · 可用 ${money(p.available)}</div><div class="row">${actionsFor(p,'projects')}</div></div>`).join(''):'<p class="muted">由业务申请账号创建第一条立项。</p>'}</div><div class="card"><h2>采购、验收与财务</h2>${businessUser.role==='applicant'?`<form id="business-purchase"><label><span>已批准项目</span><select name="projectId">${choices.map(p=>`<option value="${esc(p.id)}">${esc(p.title)} · 可用 ${money(p.available)}</option>`).join('')}</select></label><label><span>采购内容</span><input name="title" maxlength="200" required placeholder="灯光与舞台耗材"></label><div class="two"><label><span>供应商</span><input name="supplier" maxlength="200" required placeholder="虚构供应商"></label><label><span>采购总额（元）</span><input name="amount" type="number" min="0.01" step="0.01" value="3000" required></label></div><button ${choices.length?'':'disabled'}>创建采购申请</button></form>`:''}${d.purchases.slice(0,50).map(p=>`<div class="item"><b>${esc(p.title)}</b> ${badge(p.status)}<div class="muted">${esc(p.id)} · v${p.version}<br>${esc(p.supplier)} · ${money(p.amount)}</div><div class="row">${actionsFor(p,'purchases')}</div></div>`).join('')}</div></section><section><div class="card"><h2>实时项目经营</h2><label><span>选择项目</span><select id="business-project-choice">${d.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===projectChoice?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>${selectedProject?`<pre>预算：${money(selectedProject.budget)}\n基准成本：${money(selectedProject.baseline_spent)}\n新增已付采购：${money(selectedProject.paid)}\n待履约占用：${money(selectedProject.committed)}\n可用预算：${money(selectedProject.available)}</pre>`:''}<h3>资料与来源</h3>${d.evidence.filter(e=>e.project_id===projectChoice).map(e=>`<div class="item"><b>${esc(e.title)}</b><div class="muted">${esc(e.id)} · ${esc(e.kind)}</div></div>`).join('')||'<p class="muted">还没有上传文字资料。</p>'}${['applicant','buyer'].includes(businessUser.role)?`<form id="business-evidence"><label><span>资料标题</span><input name="title" required maxlength="200" placeholder="供应商报价单"></label><label><span>资料类型</span><select name="kind"><option>报价单</option><option>合同</option><option>预算方案</option><option>验收依据</option></select></label><label><span>资料正文</span><textarea name="content" rows="4" required maxlength="16000" placeholder="粘贴用于分析的虚构报价或合同条款"></textarea></label><button>保存项目资料</button></form>`:''}<form id="business-analysis"><label><span>AI 分析问题</span><input name="question" maxlength="1000" value="检查项目预算、采购和资料缺失风险"></label><button>分析实时数据并引用资料</button></form><pre id="business-evidence-answer">AI 只读资料和实时金额，不执行审批。引用编号会校验是否存在。</pre></div><div class="card"><h2>最新服务端审计</h2>${d.audit.slice(0,15).map(a=>`<div class="item"><b>${esc(a.action)}</b> · ${esc(a.actor)}<div class="muted">${esc(a.entity_id)}<br>${esc(a.created_at)}</div></div>`).join('')||'<p class="muted">尚无操作。</p>'}</div></section></div>`;};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page==='采购经营闭环'){e.stopImmediatePropagation();page='采购经营闭环';render();await refreshBusiness();return;}if(!b.dataset.business&&!b.dataset.businessAction)return;e.stopImmediatePropagation();b.disabled=true;try{if(b.dataset.business==='logout'){await businessApi('logout',{});businessUser=null;businessData=null;businessMessage='已退出，可以切换角色';}else if(b.dataset.business==='refresh'){await refreshBusiness();return;}else{await businessApi(`${b.dataset.kind}/${encodeURIComponent(b.dataset.id)}/${b.dataset.businessAction}`,{version:Number(b.dataset.version)});businessMessage='服务端操作已提交，台账已同步';}await refreshBusiness();}catch(err){businessMessage=err.message;await refreshBusiness();}finally{render();}},true);
document.addEventListener('change',e=>{if(e.target.id==='business-project-choice'){projectChoice=e.target.value;render();}});
document.addEventListener('submit',async e=>{if(!e.target.id.startsWith('business-'))return;e.preventDefault();e.stopImmediatePropagation();const formId=e.target.id,data=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('button');button.disabled=true;try{if(formId==='business-login'){const r=await businessApi('login',data);businessUser=r.user;businessMessage='登录成功';}else if(formId==='business-project'){const r=await businessApi('projects',data);projectChoice=r.id;businessMessage='立项草稿已保存';}else if(formId==='business-purchase'){await businessApi('purchases',data);businessMessage='采购申请已保存';}else if(formId==='business-evidence'){await businessApi('evidence',{...data,projectId:projectChoice});businessMessage='资料已保存，可用于 AI 分析';}else if(formId==='business-analysis'){const output=document.getElementById('business-evidence-answer');output.textContent='正在检索项目资料并调用模型…';const r=await businessApi('analyze',{...data,projectId:projectChoice});output.textContent=r.text+'\n\n引用校验：'+JSON.stringify(r.citationValidation)+'\n\n原始资料：\n'+r.documents.map(d=>`[${d.id}] ${d.title}\n${d.content}`).join('\n\n');return;}await refreshBusiness();}catch(err){if(formId==='business-analysis')document.getElementById('business-evidence-answer').textContent=err.message;else{businessMessage=err.message;render();}}finally{button.disabled=false;}},true);
page='采购经营闭环';render();refreshBusiness();
